/**
 * ctzb-dashboard — the ETH Setup Standard dashboard, served from Cloudflare.
 *
 * GENERATED by cloudflare/build_dashboard.py from docs/artifacts/eth-setup-standard.html
 * (the page) and cloudflare/dashboard_shim.js (a stand-in for the Dashboard artifact
 * type's runtime). Edit those, then rebuild. Do not edit this file by hand.
 *
 * Replaces a Claude scheduled task that uploaded every CSV to a claude.ai artifact six
 * times a day (item 17f). The page reads the pipeline's datasets live, through this
 * Worker, from the ctzb-feed mirror over a Service Binding -- Worker to Worker, no
 * public hop -- so the mirror can later be locked down without breaking this page.
 *
 * Bindings:
 *   MIRROR              Service Binding -> the ctzb-feed Worker
 *   GATE_MODE           plain var: "access" (Cloudflare Access) or "password"
 *   ACCESS_TEAM_DOMAIN  plain var, access mode: e.g. "ethkros.cloudflareaccess.com"
 *   ACCESS_AUD          plain var, access mode: the Access application's AUD tag
 *   DASHBOARD_PASSWORD  secret, password mode only
 *
 * THE GATE FAILS CLOSED. Every path, /health included, is refused unless the configured
 * gate passes, and an unset or unknown GATE_MODE refuses everything. In access mode the
 * Access JWT's signature, audience, issuer and expiry are all verified here, so turning
 * Access off by mistake -- or reaching the Worker by a preview URL that Access does not
 * cover -- still gets nothing.
 */

const PAGE = __PAGE__;
const DATASET = /^\/data\/datasets\/([a-z0-9_]{1,64}\.csv)$/;
const CERT_TTL_MS = 60 * 60 * 1000;
let certCache = { at: 0, team: "", keys: [] };

const SEC_HEADERS = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "no-referrer",
  "x-frame-options": "DENY",
};
const PAGE_CSP =
  "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; " +
  "connect-src 'self'; img-src 'self' data:; font-src 'self' data:; base-uri 'none'; " +
  "form-action 'none'; frame-ancestors 'none'";

function deny(status, msg, extra) {
  return new Response(msg, {
    status,
    headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store", ...SEC_HEADERS, ...(extra || {}) },
  });
}

/* ---------- base64url / JWT ---------- */
function b64urlToBytes(s) {
  s = s.replace(/-/g, "+").replace(/_/g, "/");
  while (s.length % 4) s += "=";
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
const b64urlJSON = (s) => JSON.parse(new TextDecoder().decode(b64urlToBytes(s)));

async function accessKeys(team, fetchImpl) {
  const now = Date.now();
  if (certCache.team === team && now - certCache.at < CERT_TTL_MS && certCache.keys.length) return certCache.keys;
  const res = await fetchImpl(`https://${team}/cdn-cgi/access/certs`);
  if (!res.ok) throw new Error("certs " + res.status);
  const j = await res.json();
  certCache = { at: now, team, keys: Array.isArray(j.keys) ? j.keys : [] };
  return certCache.keys;
}

/** True only for a token Cloudflare Access issued for THIS application, unexpired. */
async function verifyAccessJwt(token, env, fetchImpl = fetch, nowSec = Math.floor(Date.now() / 1000)) {
  const team = env.ACCESS_TEAM_DOMAIN, aud = env.ACCESS_AUD;
  if (!token || !team || !aud) return false;
  const parts = token.split(".");
  if (parts.length !== 3) return false;
  let header, payload;
  try { header = b64urlJSON(parts[0]); payload = b64urlJSON(parts[1]); } catch (_) { return false; }
  if (header.alg !== "RS256" || !header.kid) return false;
  let keys;
  try { keys = await accessKeys(team, fetchImpl); } catch (_) { return false; }
  const jwk = keys.find((k) => k.kid === header.kid);
  if (!jwk) return false;
  let ok = false;
  try {
    const key = await crypto.subtle.importKey("jwk", { kty: jwk.kty, n: jwk.n, e: jwk.e, alg: "RS256", ext: true },
      { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["verify"]);
    ok = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, b64urlToBytes(parts[2]),
      new TextEncoder().encode(parts[0] + "." + parts[1]));
  } catch (_) { return false; }
  if (!ok) return false;
  const auds = Array.isArray(payload.aud) ? payload.aud : [payload.aud];
  if (!auds.includes(aud)) return false;
  if (payload.iss !== `https://${team}`) return false;
  if (typeof payload.exp !== "number" || payload.exp <= nowSec) return false;
  if (typeof payload.nbf === "number" && payload.nbf > nowSec + 60) return false;
  return true;
}

/* ---------- password mode ---------- */
async function sameSecret(a, b) {
  // Compare digests in constant time, so the comparison leaks neither content nor length.
  const enc = new TextEncoder();
  const [x, y] = await Promise.all([crypto.subtle.digest("SHA-256", enc.encode(a)), crypto.subtle.digest("SHA-256", enc.encode(b))]);
  const u = new Uint8Array(x), v = new Uint8Array(y);
  let diff = 0;
  for (let i = 0; i < u.length; i++) diff |= u[i] ^ v[i];
  return diff === 0;
}

async function passwordOk(req, env) {
  const want = env.DASHBOARD_PASSWORD;
  if (!want) return false;
  const h = req.headers.get("authorization") || "";
  if (!h.startsWith("Basic ")) return false;
  let decoded = "";
  try { decoded = atob(h.slice(6)); } catch (_) { return false; }
  const pw = decoded.slice(decoded.indexOf(":") + 1);
  return sameSecret(pw, want);
}

/** null when the request may proceed; otherwise the refusal to send. */
async function gate(req, env, fetchImpl = fetch) {
  if (env.GATE_MODE === "access") {
    const ok = await verifyAccessJwt(req.headers.get("cf-access-jwt-assertion"), env, fetchImpl);
    return ok ? null : deny(403, "Forbidden");
  }
  if (env.GATE_MODE === "password") {
    return (await passwordOk(req, env)) ? null
      : deny(401, "Login required", { "www-authenticate": 'Basic realm="ETH Setup Standard", charset="UTF-8"' });
  }
  return deny(503, "Dashboard gate not configured");   // fail closed
}

async function handle(req, env, fetchImpl = fetch) {
  const refusal = await gate(req, env, fetchImpl);
  if (refusal) return refusal;
  if (req.method !== "GET" && req.method !== "HEAD") return deny(405, "Read-only");

  const { pathname } = new URL(req.url);
  if (pathname === "/" || pathname === "/index.html") {
    return new Response(req.method === "HEAD" ? null : PAGE, {
      headers: { "content-type": "text/html; charset=utf-8", "cache-control": "private, no-store",
                 "content-security-policy": PAGE_CSP, ...SEC_HEADERS },
    });
  }
  const m = pathname.match(DATASET);
  if (m) {
    if (!env.MIRROR) return deny(503, "Mirror binding missing");
    const r = await env.MIRROR.fetch(new Request("https://mirror/datasets/" + m[1]));
    if (!r.ok) return deny(r.status === 404 ? 404 : 502, "Dataset unavailable");
    return new Response(req.method === "HEAD" ? null : r.body, {
      headers: { "content-type": "text/csv; charset=utf-8", "cache-control": "private, no-store",
                 "x-ctzb-stale": r.headers.get("x-ctzb-stale") || "unknown", ...SEC_HEADERS },
    });
  }
  if (pathname === "/health") {
    let mirror = "unreachable";
    try { const r = await env.MIRROR.fetch(new Request("https://mirror/health")); mirror = r.ok ? "ok" : String(r.status); } catch (_) {}
    return new Response(JSON.stringify({ ok: mirror === "ok", gate: env.GATE_MODE, mirror }, null, 2), {
      headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...SEC_HEADERS },
    });
  }
  return deny(404, "Not found");
}

export default {
  fetch(req, env) { return handle(req, env); },
};
